{
  "probability": 0.33,
  "range_low": 0.28,
  "range_high": 0.38,
  "summary": [
    "Opposition consolidation around the Tisza platform could raise the anti-Fidesz bloc's chances of reaching a 2/3 seat share.",
    "Electoral-system bias in seat conversion favoring Fidesz and poll dispersion reduce the likelihood of a guaranteed 2/3 majority.",
    "Entry of Our Homeland into Parliament fragments the anti-Fidesz vote and complicates achieving a single 2/3 path.",
    "Turnout dynamics and cross-polling results add uncertainty, keeping the outcome close to the historical base rate but not guaranteed."
  ],
  "confidence": "high",
  "narrative": "Bayesian updating against a historical baseline of roughly 44% for a 2/3 majority yields a posterior near 33%. The landscape is highly contested; structural advantages for Fidesz and poll dispersion weigh against, while opposition consolidation and turnout developments offer some upside, resulting in a calibrated probability around one-third.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical base rate: 2/3 majorities occurred in 4 of 9 post-1990 Hungarian elections; reference class defined as post-1990 elections with a 133-seat threshold."
    },
    "factor_updates": [
      {
        "factor": "Electoral-system bias in seat conversion favoring Fidesz",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "The current electoral rules have repeatedly translated vote shares into a 2/3 seat majority for Fidesz, reducing the odds of a rival bloc reaching 133 seats even with broad support."
      },
      {
        "factor": "Opposition consolidation around the Tisza platform",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Uniting around Tisza elevates the anti-Fidesz bloc's seat potential in some polls, partially offsetting structural bias."
      },
      {
        "factor": "Entry of Our Homeland into parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Fragmentation of anti-Fidesz vote and new seat allocations could hinder a clean 2/3 path for either side."
      },
      {
        "factor": "Polling divergence and uncertainty about the 2/3 path",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Lack of consensus on who can secure 133 seats lowers confidence in achieving 2/3, despite some polls showing gains for Tisza."
      },
      {
        "factor": "Mobilization of inactive Fidesz supporters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Potential turnout boost for Fidesz could push seat counts back toward 2/3, offsetting other downward pressures."
      }
    ],
    "synthesis_rationale": "The posterior probability is a synthesis of anchors and updates: a relatively strong downward bias from the institutional bias and fragmentation, a moderate upward offset from possible opposition consolidation and turnout mobilization, and an overall posterior of 0.33. Calibration reflects uncertainty in turnout and coalition dynamics; therefore the range accounts for plausible variation around the central estimate."
  }
}

{
  "probability": 0.33,
  "range_low": 0.26,
  "range_high": 0.40,
  "summary": [
    "Baseline anchor from the post-1990 reference class implies a 44% historical probability of a 2/3 majority.",
    "Recent developments show significant opposition consolidation around Tisza and the entry of Our Homeland, which could threaten a 2/3 outcome for any side.",
    "Electoral-system bias in seat conversion remains a strong headwind for the anti-Fidesz bloc, limiting their chances even if polls tighten.",
    "The Bayesian posterior is 33%, reflecting substantial uncertainty and the possibility of both sides achieving the threshold, with a current leaning away from a guaranteed 2/3 victory."
  ],
  "confidence": "medium",
  "narrative": "Using the reference-class anchor of past two-thirds outcomes, updated by opposition consolidation, coalition dynamics, and structural seat conversion advantages for Fidesz, the calibrated posterior remains modest at about one-third. The range reflects substantial uncertainty given poll divergence and turnout unknowns.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Post-1990 Hungarian elections show 2/3 majorities four times (2010, 2014, 2018, 2022) out of nine elections; 0.44 is the straightforward historical base rate."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation around the Tisza platform",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation raises anti-Fidesz vote efficiency but is offset by other structural and turnout factors."
      },
      {
        "factor": "Entry of Our Homeland into parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Fragmentation of the anti-Fidesz vote can undermine pursuit of a single 2/3 bloc."
      },
      {
        "factor": "Mobilization of previously inactive Fidesz supporters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Could raise Fidesz seat share if turnout surges; serves as a counterbalance to opposition gains."
      },
      {
        "factor": "Divergent polls and uncertain seat projections",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Poll dispersion adds uncertainty and prevents confident prediction of a 2/3 outcome."
      },
      {
        "factor": "Electoral-system bias favoring Fidesz in seat conversion",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "History shows Fidesz converts votes into seats efficiently; this remains a strong dampener on anti-Fidesz 2/3 chances."
      }
    ],
    "synthesis_rationale": "The posterior (0.33) results from combining a moderate upshot from opposition consolidation with several strong downshots from systemic bias and vote fragmentation, minus some offsetting ups from mobilization. The range accommodates ongoing uncertainty in turnout and cross-poll results; given the available evidence, the 2/3 outcome remains plausible but unlikely."
  }
}

