    "factor_updates": [
      {
        "factor": "Opposition consolidation around the Tisza platform (Tisza/Our Homeland coalition)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT and Reuters/AP reporting of opposition unity around Tisza, with some polls showing Tisza ahead, raises the probability of challenging the 2/3 threshold."
      },
      {
        "factor": "Entry of Our Homeland into parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls suggesting Our Homeland crossing threshold fragments anti-Fidesz vote, complicating a clean 2/3 path for any single bloc."
      },
      {
        "factor": "Mobilization of previously inactive Fidesz supporters",
        "direction": "up",
        " magnitude": "moderate",
        "rationale": "Evidence of substantial mobilization potential could lift Fidesz seat counts if turnout increases."
      },
      {
        "factor": "Widely divergent polls and uncertain seat projections",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Cross-pirm poll dispersion across firms creates substantial uncertainty about reaching 133 seats, not pointing to a clear majority for either side."
      },
      {
        "factor": "Electoral-system bias in seat conversion favoring Fidesz",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Historical pattern of converting votes to seats favors Fidesz, depressing the odds of a novel 2/3 outcome for opponents even with coalition gains."
      }
    ],
    "synthesis_rationale": "Starting from a 0.44 anchor, the updated factors yield a net modest tilt toward contested outcomes: opposition consolidation and turnout risks push probability up from the anchor, while Our Homeland entry and the electoral-system bias pull it back down. The combination yields a calibrated mid-range probability with a relatively wide credible interval, reflecting substantial turnout and coalition uncertainty. Calibration acknowledges that while a 2/3 majority is possible, it is not the most probable given current signals."
  }
}
